1	// andes-sim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
2	// and future backends). One C++20 binary that selects a model (fast / accurate
3	// / hybrid), resolves engines at runtime, and either passes through to a single
4	// engine or orchestrates a hybrid round-trip.
5	//
6	// This file owns argument dispatch only: parse the CLI, route to a command.
7	// Each subcommand below resolves to its handler as its feature lands (F1-F13);
8	// until then it stubs out, keeping the command surface stable.
9	#include <cstdio>
10	#include <exception>
11	#include <string>
12	#include <string_view>
13	
14	#include "cli.hpp"
15	#include "repo_root.hpp"
16	
17	namespace andes_sim {
18	int cmd_list(const Cli& cli);
19	}  // namespace andes_sim
20	
21	namespace {
22	
23	using andes_sim::Cli;
24	
25	struct Subcommand {
26	  std::string_view name;
27	  std::string_view brief;
28	};
29	
30	// The full command surface. Names are fixed from F0 so usage, dispatch, and
31	// tests are stable; handlers arrive feature by feature.
32	constexpr Subcommand kSubcommands[] = {
33	    {"build", "build artifacts (qemu, vsim, plugin, simpoint, fixtures, driver)"},
34	    {"run", "run one simulation (--model fast|accurate|hybrid)"},
35	    {"test", "run the end-to-end suite"},
36	    {"list", "list fixtures|models|engines"},
37	    {"doctor", "check environment health"},
38	    {"profile", "profile a workload into a basic-block vector"},
39	    {"cluster", "cluster a BBV into SimPoint phases"},
40	    {"archive", "snapshot a drained state into a replayable dir"},
41	    {"replay", "replay a snapshot"},
42	    {"estimate", "whole-program cycle estimate (run --model hybrid --trigger simpoint)"},
43	};
44	
45	const Subcommand* find(std::string_view name) {
46	  for (const Subcommand& s : kSubcommands)
47	    if (s.name == name) return &s;
48	  return nullptr;
49	}
50	
51	void print_usage(std::FILE* out) {
52	  std::fputs("usage: andes-sim <cmd> [args...]\n\n", out);
53	  std::fputs("Multi-engine driver for the Andes simulators (QEMU + Verilator).\n\n",
54	             out);
55	  std::fputs("commands:\n", out);
56	  for (const Subcommand& s : kSubcommands)
57	    std::fprintf(out, "  %-9.*s  %.*s\n", static_cast<int>(s.name.size()),
58	                 s.name.data(), static_cast<int>(s.brief.size()), s.brief.data());
59	}
60	
61	void print_subcommand_help(const Subcommand& sc, std::FILE* out) {
62	  std::fprintf(out, "usage: andes-sim %.*s [args...]\n\n",
63	               static_cast<int>(sc.name.size()), sc.name.data());
64	  std::fprintf(out, "%.*s\n", static_cast<int>(sc.brief.size()), sc.brief.data());
65	  if (sc.name == "run") {
66	    std::fputs(
67	        "\nselection:\n"
68	        "  --model fast|accurate|hybrid       which composition to run\n"
69	        "  --engine <id>                      pick a specific engine "
70	        "(e.g. verilator:ax45mpv_premium)\n"
71	        "  --trigger csr|pc|icount|simpoint   ROI delimiter (hybrid only)\n"
72	        "  -- <args...>                       forward everything after -- "
73	        "verbatim to the engine\n",
74	        out);
75	  } else if (sc.name == "list") {
76	    std::fputs("\ntargets: fixtures | models | engines\n", out);
77	  }
78	}
79	
80	}  // namespace
81	
82	int main(int argc, char** argv) {
83	  using namespace andes_sim;
84	
85	  Cli cli = parse_cli(argc, argv);
86	  if (!cli.error.empty()) {
87	    std::fprintf(stderr, "andes-sim: %s\n", cli.error.c_str());
88	    return 2;
89	  }
90	
91	  if (cli.subcommand.empty()) {  // no command, or top-level -h
92	    if (cli.help) {
93	      print_usage(stdout);
94	      return 0;
95	    }
96	    print_usage(stderr);
97	    return 2;
98	  }
99	
100	  const Subcommand* sc = find(cli.subcommand);
101	  if (!sc) {
102	    std::fprintf(stderr, "andes-sim: unknown command '%s'\n\n",
103	                 cli.subcommand.c_str());
104	    print_usage(stderr);
105	    return 2;
106	  }
107	
108	  if (cli.help) {
109	    print_subcommand_help(*sc, stdout);
110	    return 0;
111	  }
112	
113	  if (cli.subcommand == "list") return cmd_list(cli);
114	
115	  // Remaining subcommands stub out until their feature lands. Resolve the repo
116	  // root so the discovery path stays live and observable.
117	  std::string root;
118	  try {
119	    root = repo_root().string();
120	  } catch (const std::exception& e) {
121	    root = std::string("<unknown: ") + e.what() + ">";
122	  }
123	  std::fprintf(stderr, "andes-sim %s: not yet implemented (repo root: %s)\n",
124	               cli.subcommand.c_str(), root.c_str());
125	  return 3;
126	}
