1	// Unit tests for the andes-sim CLI parser (parse_cli).
2	//
3	// Plain assert-and-count harness (no doctest dependency on the driver side).
4	// Exits non-zero if any check fails. Run by tests/andes_sim/test_andes_sim_f1.sh
5	// and, later, the F5+ infra tests.
6	#include <cstdio>
7	#include <string>
8	#include <vector>
9	
10	#include "cli.hpp"
11	
12	using andes_sim::Cli;
13	using andes_sim::parse_cli;
14	
15	static int g_failures = 0;
16	
17	#define CHECK(cond)                                                       \
18	  do {                                                                    \
19	    if (!(cond)) {                                                        \
20	      std::fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
21	      ++g_failures;                                                       \
22	    }                                                                     \
23	  } while (0)
24	
25	int main() {
26	  // Selection axes, space-separated form.
27	  {
28	    Cli c = parse_cli({"run", "--model", "fast", "--engine",
29	                       "verilator:ax45mpv_premium", "--trigger", "csr",
30	                       "prog.elf"});
31	    CHECK(c.error.empty());
32	    CHECK(c.subcommand == "run");
33	    CHECK(c.model == "fast");
34	    CHECK(c.engine == "verilator:ax45mpv_premium");
35	    CHECK(c.trigger == "csr");
36	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
37	    CHECK(!c.has_passthrough);
38	    CHECK(c.passthrough.empty());
39	  }
40	
41	  // Selection axes, --flag=value form.
42	  {
43	    Cli c = parse_cli({"run", "--model=accurate", "--engine=verilator:x"});
44	    CHECK(c.error.empty());
45	    CHECK(c.model == "accurate");
46	    CHECK(c.engine == "verilator:x");
47	  }
48	
49	  // The `--` boundary: everything after it is verbatim passthrough, even
50	  // tokens that look like framework flags (they must NOT be parsed).
51	  {
52	    Cli c = parse_cli({"run", "--model", "fast", "prog.elf", "--", "-gdb",
53	                       "tcp::1234", "-S", "--model", "IGNORED"});
54	    CHECK(c.error.empty());
55	    CHECK(c.model == "fast");
56	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
57	    CHECK(c.has_passthrough);
58	    CHECK(c.passthrough.size() == 5);
59	    CHECK(c.passthrough[0] == "-gdb");
60	    CHECK(c.passthrough[1] == "tcp::1234");
61	    CHECK(c.passthrough[4] == "IGNORED");
62	  }
63	
64	  // A `--` with nothing after it still marks passthrough (empty argv).
65	  {
66	    Cli c = parse_cli({"run", "--model", "fast", "--"});
67	    CHECK(c.error.empty());
68	    CHECK(c.has_passthrough);
69	    CHECK(c.passthrough.empty());
70	  }
71	
72	  // Per-subcommand help.
73	  {
74	    Cli c = parse_cli({"run", "-h"});
75	    CHECK(c.subcommand == "run");
76	    CHECK(c.help);
77	  }
78	  {
79	    Cli c = parse_cli({"list", "--help"});
80	    CHECK(c.subcommand == "list");
81	    CHECK(c.help);
82	  }
83	
84	  // Top-level help: no subcommand.
85	  {
86	    Cli c = parse_cli({"-h"});
87	    CHECK(c.subcommand.empty());
88	    CHECK(c.help);
89	  }
90	
91	  // list positional target.
92	  {
93	    Cli c = parse_cli({"list", "fixtures"});
94	    CHECK(c.subcommand == "list");
95	    CHECK(c.positional.size() == 1 && c.positional[0] == "fixtures");
96	  }
97	
98	  // Unknown option before `--` is an error.
99	  {
100	    Cli c = parse_cli({"run", "--bogus"});
101	    CHECK(!c.error.empty());
102	  }
103	
104	  // A selection flag with no value is an error.
105	  {
106	    Cli c = parse_cli({"run", "--model"});
107	    CHECK(!c.error.empty());
108	  }
109	
110	  if (g_failures) {
111	    std::fprintf(stderr, "%d check(s) failed\n", g_failures);
112	    return 1;
113	  }
114	  std::printf("all cli parse checks passed\n");
115	  return 0;
116	}
