22	namespace fs = std::filesystem;
23	
24	namespace andes_sim {
25	namespace {
26	
27	std::string ljust(std::string s, size_t w) {
28	  if (s.size() < w) s.append(w - s.size(), ' ');
29	  return s;
30	}
31	
32	std::vector<std::string> read_lines(const fs::path& p, bool& ok) {
33	  std::ifstream f(p);
34	  std::vector<std::string> lines;
35	  ok = static_cast<bool>(f);
36	  if (!ok) return lines;
37	  std::string line;
38	  while (std::getline(f, line)) lines.push_back(line);
39	  return lines;
40	}
41	
42	// Match a Makefile variable assignment at column 0: `VAR :?= <body>` where
43	// VAR is [A-Z_][A-Z0-9_]*. Mirrors the Python regex anchor. On success sets
44	// `var` and `body` (the text after `=`, continuation backslash included).
45	bool parse_assignment(const std::string& line, std::string& var,
46	                      std::string& body) {
47	  const size_t n = line.size();
48	  if (n == 0) return false;
49	  char c0 = line[0];
50	  if (!((c0 >= 'A' && c0 <= 'Z') || c0 == '_')) return false;
51	  size_t p = 0;
52	  while (p < n) {
53	    char c = line[p];
54	    if ((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') ++p;
55	    else break;
56	  }
57	  var = line.substr(0, p);
58	  while (p < n && (line[p] == ' ' || line[p] == '\t')) ++p;  // \s*
59	  if (p < n && line[p] == ':') ++p;                          // :?
60	  if (p >= n || line[p] != '=') return false;                // =
61	  ++p;
62	  body = line.substr(p);
63	  return true;
64	}
65	
66	struct Fixture {
67	  std::string name;
68	  std::string family;
69	};
70	
71	// Extract fixture (name, family) rows from tests/fixtures/Makefile in stable,
72	// family-grouped, file order; dedupe globally; append handoff_roundtrip last.
73	std::vector<Fixture> parse_fixtures(const std::vector<std::string>& lines) {
74	  static const std::pair<std::string, std::string> interesting[] = {
75	      {"RT_FIXTURES", "asm"},
76	      {"RT_C_FIXTURES", "c"},
77	      {"RT_C_V_FIXTURES", "c+rvv"},
78	      {"PROBE_V_FIXTURES", "probe"},
79	  };
80	  std::vector<Fixture> rows;
81	  std::set<std::string> seen;
82	
83	  for (size_t k = 0; k < lines.size(); ++k) {
84	    std::string var, body;
85	    if (!parse_assignment(lines[k], var, body)) continue;
86	    std::string family;
87	    for (const auto& it : interesting)
88	      if (it.first == var) { family = it.second; break; }
89	    if (family.empty()) continue;
90	
91	    // Splice continuation lines: a trailing backslash + newline becomes a space.
92	    size_t li = k;
93	    while (!body.empty() && body.back() == '\\') {
94	      body.pop_back();
95	      body.push_back(' ');
96	      if (++li < lines.size()) body += lines[li];
97	      else break;
98	    }
99	
100	    std::istringstream iss(body);
101	    std::string name;
102	    while (iss >> name)
103	      if (seen.insert(name).second) rows.push_back({name, family});
104	  }
105	
106	  // handoff_roundtrip is not in a *_FIXTURES var; list it explicitly.
107	  if (seen.insert("handoff_roundtrip").second)
108	    rows.push_back({"handoff_roundtrip", "asm"});
109	
110	  return rows;
111	}
112	
113	int list_fixtures() {
114	  fs::path mk = repo_root() / "tests" / "fixtures" / "Makefile";
115	  bool ok;
116	  std::vector<std::string> lines = read_lines(mk, ok);
117	  if (!ok) {
118	    std::fprintf(stderr, "andes-sim: missing %s\n", mk.c_str());
119	    return 2;
120	  }
121	  std::vector<Fixture> rows = parse_fixtures(lines);
122	
123	  size_t width = 0;
124	  for (const Fixture& r : rows) width = std::max(width, r.name.size());
125	
126	  std::printf("%s  FAMILY\n", ljust("FIXTURE", width).c_str());
127	  for (const Fixture& r : rows)
128	    std::printf("%s  %s\n", ljust(r.name, width).c_str(), r.family.c_str());
129	  return 0;
130	}
