132	int list_models() {
133	  size_t wn = 5, we = 7;  // header widths: MODEL, ENGINES
134	  for (const Model& m : kModels) {
135	    wn = std::max(wn, m.name.size());
136	    we = std::max(we, m.engines.size());
137	  }
138	  std::printf("%s  %s  NOTES\n", ljust("MODEL", wn).c_str(),
139	              ljust("ENGINES", we).c_str());
140	  for (const Model& m : kModels)
141	    std::printf("%s  %s  %s\n", ljust(std::string(m.name), wn).c_str(),
142	                ljust(std::string(m.engines), we).c_str(),
143	                std::string(m.notes).c_str());
144	  return 0;
145	}
146	
147	int list_engines() {
148	  Discovery disc = discover_engines();
149	
150	  auto join = [](const std::vector<std::string>& v) {
151	    std::string s;
152	    for (size_t k = 0; k < v.size(); ++k) {
153	      if (k) s += ",";
154	      s += v[k];
155	    }
156	    return s;
157	  };
158	  auto vlen_str = [](long v) {
159	    return v > 0 ? std::to_string(v) : std::string("-");
160	  };
161	
162	  size_t we = 6, wt = 4, wk = 4, wv = 4;  // ENGINE, TYPE, KIND, VLEN headers
163	  for (const EngineDescriptor& e : disc.engines) {
164	    we = std::max(we, e.id.size());
165	    wt = std::max(wt, e.type.size());
166	    wk = std::max(wk, e.kind.size());
167	    wv = std::max(wv, vlen_str(e.vlen).size());
168	  }
169	
170	  std::printf("%s  %s  %s  %s  TRIGGERS\n", ljust("ENGINE", we).c_str(),
171	              ljust("TYPE", wt).c_str(), ljust("KIND", wk).c_str(),
172	              ljust("VLEN", wv).c_str());
173	  for (const EngineDescriptor& e : disc.engines)
174	    std::printf("%s  %s  %s  %s  %s\n", ljust(e.id, we).c_str(),
175	                ljust(e.type, wt).c_str(), ljust(e.kind, wk).c_str(),
176	                ljust(vlen_str(e.vlen), wv).c_str(), join(e.triggers).c_str());
177	
178	  // Binaries that could not self-describe are reported, never silently dropped.
179	  for (const std::string& w : disc.warnings)
180	    std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
181	  return 0;
182	}
183	
184	}  // namespace
185	
186	int cmd_list(const Cli& cli) {
187	  if (cli.positional.empty()) {
188	    std::fprintf(stderr,
189	                 "andes-sim list: expected one of fixtures|models|engines\n");
190	    return 2;
191	  }
192	  const std::string& t = cli.positional[0];
193	  if (t == "fixtures") return list_fixtures();
194	  if (t == "models") return list_models();
195	  if (t == "engines") return list_engines();
196	  std::fprintf(
197	      stderr,
198	      "andes-sim list: unknown target '%s' (want fixtures|models|engines)\n",
199	      t.c_str());
200	  return 2;
201	}
