13	
14	static int g_failures = 0;
15	#define CHECK(cond)                                                       \
16	  do {                                                                    \
17	    if (!(cond)) {                                                        \
18	      std::fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
19	      ++g_failures;                                                       \
20	    }                                                                     \
21	  } while (0)
22	
23	int main() {
24	  // A representative engine descriptor.
25	  const char* doc = R"({
26	    "id": "verilator:ax45mpv_premium",
27	    "type": "verilator",
28	    "kind": "cycle-accurate",
29	    "vlen": 512, "xlen": 64,
30	    "triggers": ["csr", "pc", "icount"],
31	    "roles": ["standalone", "accurate-leg"],
32	    "state": ["resume", "drain"],
33	    "invoke": {
34	      "standalone": ["{bin}", "{elf}"],
35	      "accurate-leg": ["{bin}", "--resume-from-qemu", "{state_in}"]
36	    },
37	    "result": "stderr:cycles"
38	  })";
39	
40	  json::Parsed p = json::parse(doc);
41	  CHECK(p.ok);
42	  CHECK(p.value.is_object());
43	
44	  const json::Value& v = p.value;
45	  CHECK(v.find("id") != nullptr);
46	  CHECK(v.find("id")->as_string() == "verilator:ax45mpv_premium");
47	  CHECK(v.find("type")->as_string() == "verilator");
48	  CHECK(v.find("vlen")->is_number());
49	  CHECK(v.find("vlen")->as_int() == 512);
50	  CHECK(v.find("xlen")->as_int() == 64);
51	  CHECK(v.find("missing") == nullptr);
52	
53	  // arrays of strings
54	  const json::Value* trig = v.find("triggers");
55	  CHECK(trig && trig->is_array());
56	  std::vector<std::string> trigs = trig->as_string_array();
57	  CHECK(trigs.size() == 3);
58	  CHECK(trigs[0] == "csr" && trigs[2] == "icount");
59	
60	  // nested object + nested array
61	  const json::Value* inv = v.find("invoke");
62	  CHECK(inv && inv->is_object());
63	  const json::Value* leg = inv->find("accurate-leg");
64	  CHECK(leg && leg->is_array());
65	  CHECK(leg->as_string_array().size() == 3);
66	  CHECK(leg->as_string_array()[1] == "--resume-from-qemu");
67	
68	  // literals + escapes + whitespace tolerance
69	  {
70	    json::Parsed q = json::parse(R"({"a":true,"b":false,"c":null,"d":-3.5})");
71	    CHECK(q.ok);
72	    CHECK(q.value.find("a")->type == json::Value::Type::Bool);
73	    CHECK(q.value.find("a")->b == true);
74	    CHECK(q.value.find("c")->type == json::Value::Type::Null);
75	    CHECK(q.value.find("d")->is_number());
76	  }
77	  {
78	    json::Parsed q = json::parse(R"("a\tb\"c")");
79	    CHECK(q.ok);
80	    CHECK(q.value.is_string());
81	    CHECK(q.value.str == "a\tb\"c");
82	  }
83	  {
84	    json::Parsed q = json::parse("   [ 1 , 2 ,3 ]  ");
85	    CHECK(q.ok);
86	    CHECK(q.value.is_array());
87	    CHECK(q.value.arr.size() == 3);
88	  }
89	
90	  // malformed inputs fail (do not crash, ok=false)
91	  for (const char* bad : {"{", "{\"a\":}", "[1,2", "tru", "\"unterminated",
92	                          "{\"a\" 1}", ""}) {
93	    json::Parsed q = json::parse(bad);
94	    CHECK(!q.ok);
95	  }
96	
97	  if (g_failures) {
98	    std::fprintf(stderr, "%d check(s) failed\n", g_failures);
99	    return 1;
100	  }
101	  std::printf("all json parse checks passed\n");
102	  return 0;
103	}
