15	long now_ms() {
16	  struct timespec ts;
17	  clock_gettime(CLOCK_MONOTONIC, &ts);
18	  return ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;
19	}
20	
21	}  // namespace
22	
23	RunResult run_process(const std::vector<std::string>& argv, int timeout_ms) {
24	  RunResult r;
25	  if (argv.empty()) {
26	    r.spawn_failed = true;
27	    return r;
28	  }
29	
30	  int fds[2];
31	  if (pipe(fds) != 0) {
32	    r.spawn_failed = true;
33	    return r;
34	  }
35	
36	  pid_t pid = fork();
37	  if (pid < 0) {
38	    close(fds[0]);
39	    close(fds[1]);
40	    r.spawn_failed = true;
41	    return r;
42	  }
43	
44	  if (pid == 0) {  // child
45	    close(fds[0]);
46	    dup2(fds[1], STDOUT_FILENO);
47	    int devnull = open("/dev/null", O_RDWR);
48	    if (devnull >= 0) {
49	      dup2(devnull, STDIN_FILENO);
50	      dup2(devnull, STDERR_FILENO);
51	      if (devnull > 2) close(devnull);
52	    }
53	    close(fds[1]);
54	    std::vector<char*> cargv;
55	    cargv.reserve(argv.size() + 1);
56	    for (const std::string& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
57	    cargv.push_back(nullptr);
58	    execvp(cargv[0], cargv.data());
59	    _exit(127);  // exec failed
60	  }
61	
62	  // parent
63	  close(fds[1]);
64	  int rfd = fds[0];
65	  const long deadline = now_ms() + timeout_ms;
66	  char buf[4096];
67	  bool killed = false;
68	
69	  while (true) {
70	    long remaining = deadline - now_ms();
71	    if (remaining < 0) remaining = 0;
72	    struct pollfd pfd{rfd, POLLIN, 0};
73	    int pr = poll(&pfd, 1, static_cast<int>(remaining));
74	    if (pr < 0) {
75	      if (errno == EINTR) continue;
76	      break;
77	    }
78	    if (pr == 0) {  // timed out with no data ready
79	      kill(pid, SIGKILL);
80	      killed = true;
81	      r.timed_out = true;
82	      break;
83	    }
84	    if (pfd.revents & (POLLIN | POLLHUP | POLLERR)) {
85	      ssize_t n = read(rfd, buf, sizeof(buf));
86	      if (n > 0) {
87	        r.out.append(buf, static_cast<size_t>(n));
88	      } else if (n == 0) {
89	        break;  // EOF: child closed stdout
90	      } else {
91	        if (errno == EINTR) continue;
92	        break;
93	      }
94	    }
95	    if (now_ms() >= deadline) {  // chatty child kept us past the deadline
96	      kill(pid, SIGKILL);
97	      killed = true;
98	      r.timed_out = true;
99	      break;
100	    }
101	  }
102	
103	  close(rfd);
104	  int status = 0;
105	  waitpid(pid, &status, 0);
106	  if (killed) {
107	    r.rc = -1;
108	  } else if (WIFEXITED(status)) {
109	    r.rc = WEXITSTATUS(status);
110	  } else {
111	    r.rc = -1;
112	  }
113	  return r;
114	}
