57	// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
58	// a human-readable note in `warn`.
59	bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
60	  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
61	  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
62	    json::Parsed p = json::parse(r.out);
63	    if (p.ok) {
