65	      if (err.empty()) {
66	        d.bin_path = bin.string();
67	        d.source = "--describe";
68	        return true;
69	      }
70	      warn = bin.string() + ": --describe JSON invalid: " + err;
71	    } else {
72	      warn = bin.string() + ": --describe output is not JSON: " + p.error;
73	    }
74	  }
