80	    json::Parsed p = json::parse(read_file(sidecar));
81	    if (p.ok) {
82	      EngineDescriptor sd;
83	      std::string err = descriptor_from_json(p.value, sd);
84	      if (err.empty()) {
85	        sd.bin_path = bin.string();
86	        sd.source = "sidecar";
87	        d = std::move(sd);
88	        return true;
89	      }
90	      warn = sidecar.string() + ": invalid descriptor: " + err;
91	    } else {
92	      warn = sidecar.string() + ": not JSON: " + p.error;
93	    }
94	  }
95	
96	  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
97	  return false;
98	}
