100	void scan_dir(const fs::path& dir, bool require_sim_prefix, Discovery& out,
101	              std::set<std::string>& seen) {
102	  std::error_code ec;
103	  if (!fs::is_directory(dir, ec)) return;
104	
105	  std::vector<fs::path> entries;
106	  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
107	  std::sort(entries.begin(), entries.end());  // stable, deterministic order
108	
109	  for (const fs::path& p : entries) {
110	    if (require_sim_prefix && p.filename().string().rfind("sim_", 0) != 0) continue;
111	    if (!is_executable_file(p)) continue;
112	    EngineDescriptor d;
113	    std::string warn;
114	    if (describe_one(p, d, warn)) {
115	      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
116	    } else if (!warn.empty()) {
117	      out.warnings.push_back(warn);
118	    }
119	  }
120	}
