124	Discovery discover_engines() {
125	  Discovery out;
126	  std::set<std::string> seen;
127	
128	  EngineDescriptor qemu = builtin_qemu();
129	  seen.insert(qemu.id);
130	  out.engines.push_back(std::move(qemu));
131	
132	  if (const char* env = std::getenv("ANDES_SIM_ENGINES_DIR"); env && *env) {
133	    std::stringstream ss(env);
134	    std::string dir;
135	    while (std::getline(ss, dir, ':'))
136	      if (!dir.empty()) scan_dir(dir, /*require_sim_prefix=*/false, out, seen);
137	  } else {
138	    scan_dir(repo_root() / "verilator" / "build", /*require_sim_prefix=*/true,
139	             out, seen);
140	  }
141	  return out;
142	}
