40	// Emit the andes-sim engine descriptor (see docs/engine_interface.md). This is
41	// the self-describe half of the framework's hot-plug contract: andes-sim runs
42	// `sim_<cfg> --describe`, parses this JSON, and can then drive the binary with
43	// no per-engine code. vlen/xlen come from the same embedded config.inc blob
44	// that --print-config dumps; the config name comes from VSIM_CPU_PYMODULE_NAME.
45	static void describe_engine()
46	{
47	  std::string cfg = VSIM_CPU_PYMODULE_NAME;  // "simulator_<cfg>"
48	  const std::string prefix = "simulator_";
49	  if (cfg.rfind(prefix, 0) == 0)
50	    cfg = cfg.substr(prefix.size());
51	
52	  const std::string_view blob(&_binary_config_inc_start,
53	                              static_cast<size_t>(&_binary_config_inc_end
54	                                                  - &_binary_config_inc_start));
55	  auto scan_int = [blob](std::string_view key) -> long {
56	    size_t pos = blob.find(key);
57	    if (pos == std::string_view::npos)
58	      return 0;
59	    pos += key.size();
60	    while (pos < blob.size() && (blob[pos] < '0' || blob[pos] > '9'))
61	      ++pos;
62	    long v = 0;
63	    bool any = false;
64	    while (pos < blob.size() && blob[pos] >= '0' && blob[pos] <= '9') {
65	      v = v * 10 + (blob[pos] - '0');
66	      ++pos;
67	      any = true;
68	    }
69	    return any ? v : 0;
70	  };
71	  const long vlen = scan_int("NDS_VLEN");
72	  const long xlen = scan_int("NDS_XLEN");
73	
74	  // Built by hand (not fmt) to keep the literal {bin}/{elf}/{state_in}
75	  // placeholders out of fmt's brace parser.
76	  std::string json;
77	  json += "{\n";
78	  json += "  \"id\": \"verilator:" + cfg + "\",\n";
79	  json += "  \"type\": \"verilator\",\n";
80	  json += "  \"kind\": \"cycle-accurate\",\n";
81	  json += "  \"vlen\": " + std::to_string(vlen) + ", \"xlen\": "
82	          + std::to_string(xlen) + ",\n";
83	  json += "  \"triggers\": [\"csr\", \"pc\", \"icount\"],\n";
84	  json += "  \"roles\": [\"standalone\", \"accurate-leg\"],\n";
85	  json += "  \"state\": [\"resume\", \"drain\"],\n";
86	  json += "  \"invoke\": {\n";
87	  json += "    \"standalone\": [\"{bin}\", \"{elf}\"],\n";
88	  json += "    \"accurate-leg\": [\"{bin}\", \"--resume-from-qemu\", "
89	          "\"{state_in}\", \"--handoff-out\", \"{state_out}\", "
90	          "\"--shared-mem-path\", \"{mmap}\"]\n";
91	  json += "  },\n";
92	  json += "  \"result\": \"stderr:cycles\"\n";
93	  json += "}\n";
94	  fwrite(json.data(), 1, json.size(), stdout);
95	}
